<script setup>
import DemoApiReviewPanel from "../../../docs/.vuepress/components/ApiReviewPanel.vue";
import {
  defineReviewConfig,
  ReviewSlot as DemoReviewSlot,
} from "@sparknest/ui-doc-preview";
import __apiReviewRawConfig from "./api-review-c-time-range-1.config.json";

import { ref } from "vue";
const value = ref(["09:00", "10:00"]);
const open = ref(false);
const acceptValue = ref(true);
const acceptOpen = ref(true);
const acceptClose = ref(true);
const commits = ref(0);
const proposal = ref();
const openProposal = ref();
const updateValue = (next) => {
  proposal.value = next;
  if (acceptValue.value) {
    value.value = next;
  }
};
const updateOpen = (next) => {
  openProposal.value = next;
  if (acceptOpen.value && (next || acceptClose.value)) {
    open.value = next;
  }
};
</script>

<template>
  <DemoApiReviewPanel
    v-slot="__apiReview"
    v-bind="defineReviewConfig(__apiReviewRawConfig)"
  >
    <div style="display: flex; flex-direction: column; gap: 12px; width: 100%">
      <p>非受控初始值，无需绑定 v-model</p>
      <c-time-range
        :default-value="['09:00', '10:00']"
        format="HH:mm"
        clearable
        v-bind="__apiReview.bindings"
        v-on="__apiReview.listeners"
      />
      <p>受控值与展开状态</p>
      <c-checkbox v-model="acceptValue"> 接受值更新</c-checkbox>
      <c-checkbox v-model="acceptOpen"> 接受展开更新</c-checkbox>
      <c-time-range
        :model-value="value"
        :open="open"
        format="HH:mm"
        clearable
        v-bind="__apiReview.bindings"
        @update:model-value="updateValue"
        @update:open="updateOpen"
        @change="commits++"
        v-on="__apiReview.listeners"
      />
      <span>{{ value }} / {{ open }}</span>
      <c-checkbox v-model="acceptClose"> 接受关闭请求</c-checkbox>
      <output aria-label="Commit count">{{ commits }}</output>
      <output aria-label="Controlled proposals">{{
        JSON.stringify({ value: proposal, open: openProposal })
      }}</output>
    </div>
  </DemoApiReviewPanel>
</template>
